// Diagnostic court par adresse MAC. Les valeurs rejetées ne sont PAS des mesures.
const e=msg.payload;
const now=Date.now();
const db=context.get("short_health")||{};
const addr=e&&typeof e==="object"?String(e.address||"").toUpperCase():"";
const types=[
  {id:"24S",n:24,mask:54,voltage:118,current:126,soc:141,t1:130,t2:132,mos:134},
  {id:"32S",n:32,mask:70,voltage:150,current:158,soc:173,t1:162,t2:164,mos:144}
];
function check(b,p){
 const enabled=b.readUInt32LE(p.mask),cells=[];
 for(let i=0;i<p.n;i++){
  if((enabled>>>i)&1)cells.push(b.readUInt16LE(6+i*2)/1000);
 }
 const count=cells.length,pack=b.readUInt32LE(p.voltage)/1000;
 const sum=cells.reduce((s,x)=>s+x,0);
 const soc=b[p.soc],amps=b.readInt32LE(p.current)/1000;
 const temps=[p.t1,p.t2,p.mos].map(x=>b.readInt16LE(x)/10);
 const issues=[];
 if(count<4)issues.push("cellules "+count+"/"+p.n);
 if(cells.some(v=>v<1.5||v>4.5))issues.push("cellule hors 1.5-4.5V");
 if(pack<5||pack>170)issues.push("pack "+pack.toFixed(2)+"V improbable");
 if(Math.abs(sum-pack)>Math.max(1.5,pack*0.04))
   issues.push("somme "+sum.toFixed(2)+"V / pack "+pack.toFixed(2)+"V");
 if(soc>100)issues.push("SOC brut "+soc+">100");
 if(Math.abs(amps)>3000)issues.push("courant brut >3000A");
 if(temps.some(t=>t< -80||t>160))issues.push("température hors plage");
 return {id:p.id, count, pack, sum, soc, issues};
}
if(addr){
 if(!db[addr])db[addr]={up:false,rssi:null,name:"",frameAt:0,decodeAt:0,
  format:"",rawChecks:[],lastError:""};
 const s=db[addr];
 if(e.type==="device_found"){
  if(e.name)s.name=e.name;
  if(Number.isFinite(Number(e.rssi)))s.rssi=Number(e.rssi);
 }else if(e.type==="connected"){
  s.up=true;s.lastError="";s.frameAt=0;s.decodeAt=0;s.rawChecks=[];
 }else if(e.type==="disconnected"){
  s.up=false;
 }else if(e.type==="connection_error"||e.type==="stream_stale"){
  s.lastError=String(e.error||e.type);
 }else if(e.type===2&&e.crc_ok===true){
  s.frameAt=now;
  if(typeof e.raw_hex==="string"&&/^[0-9a-fA-F]{600}$/.test(e.raw_hex)){
   const b=Buffer.from(e.raw_hex,"hex");
   if(b.length===300)s.rawChecks=types.map(p=>check(b,p));
  }
 }else if(e.validation==="provisional_compare_with_BatMON"&&e.source_crc_ok===true){
  s.decodeAt=now;s.format=e.format||"?";s.voltage=e.voltage_v;s.soc=e.soc_pct;
  s.temperatureWarning=Array.isArray(e.invalid_temperature_channels)?
    e.invalid_temperature_channels.join(","):"";
 }
 context.set("short_health",db);
 return null;
}
if(e!=="short_tick")return null;
const out=[];
for(const mac of Object.keys(db).sort()){
 const s=db[mac],tail=mac.slice(-5);
 const frameAge=s.frameAt?Math.floor((now-s.frameAt)/1000):null;
 const decodedAge=s.decodeAt?Math.floor((now-s.decodeAt)/1000):null;
 const recentFrame=frameAge!==null&&frameAge<35;
 const recentDecode=decodedAge!==null&&decodedAge<35;
 let line=tail+" | BLE "+(s.up?"OK":"OFF");
 if(s.rssi!==null)line+=" "+s.rssi+"dBm";
 line+=" | CRC "+(recentFrame?"OK "+frameAge+"s":"absent");
 if(recentDecode)line+=" | MESURES OK "+s.format+" "+s.voltage+"V SOC "+s.soc+"%"+
   (s.temperatureWarning?" | TEMP "+s.temperatureWarning+" INVALIDE":"");
 else if(recentFrame)line+=" | DÉCODAGE REJETÉ";
 else line+=" | PAS DE TRAME";
 out.push({topic:"jk/"+mac+"/etat_court",payload:line});
 if(recentFrame&&!recentDecode){
  for(const p of s.rawChecks){
   const problem=p.issues.length?p.issues[0]:"champs plausibles; format ambigu";
   out.push({topic:"jk/"+mac+"/rejet_"+p.id,
     payload:tail+" "+p.id+" REJET : "+problem+
       (p.issues.length>1?" (+"+(p.issues.length-1)+" autres)":"")});
  }
 }
}
if(out.length===0)return null;
node.status({fill:"blue",shape:"dot",text:Object.keys(db).length+" BMS suivis"});
return [out];
